INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788693923815_pkr1g', '47fc1671-0e5d-4f66-af79-ca34f5e10ec5', 'software', 'Software & Core Systems', 'beginner', '[{"id":"soft-beg-1","questionText":"What is the time complexity of searching for an element in an unsorted array of size N?","options":[{"id":"soft-beg-1-d","label":"A","text":"O(N^2) quadratic time, because comparing array elements requires nested loop iterations across all pairs"},{"id":"soft-beg-1-c","label":"B","text":"O(log N) logarithmic time, because the search space can be repeatedly halved using binary comparisons"},{"id":"soft-beg-1-b","label":"C","text":"O(1) constant time, because direct index lookups retrieve elements instantly regardless of array size"},{"id":"soft-beg-1-a","label":"D","text":"O(N) linear time, because in the worst case every element must be inspected sequentially from start to end"}],"correctOptionId":"soft-beg-1-a","difficulty":"beginner","complexity":"fundamental","conceptTag":"array-linear-search-complexity","explanationAfterAnswer":"In an unsorted array, there is no ordering to guide searches. Finding a specific element requires checking each position sequentially, leading to O(N) worst-case time complexity.","questionNumber":1},{"id":"soft-beg-2","questionText":"What distinguishes a Stack from a Queue in fundamental computer science data structures?","options":[{"id":"soft-beg-2-c","label":"A","text":"A Stack requires continuous heap memory allocation, while a Queue operates exclusively on disk storage"},{"id":"soft-beg-2-d","label":"B","text":"A Stack permits random access by integer index, while a Queue requires hash table key lookups"},{"id":"soft-beg-2-b","label":"C","text":"A Stack follows Last-In-First-Out (LIFO) order, while a Queue follows First-In-First-Out (FIFO) order"},{"id":"soft-beg-2-a","label":"D","text":"A Stack stores floating-point numbers in memory, while a Queue stores character string objects"}],"correctOptionId":"soft-beg-2-b","difficulty":"beginner","complexity":"fundamental","conceptTag":"stack-vs-queue-ordering","explanationAfterAnswer":"A Stack inserts and removes items from the same end (LIFO - like a stack of plates). A Queue inserts items at the back and removes them from the front (FIFO - like a line of people waiting).","questionNumber":2},{"id":"soft-beg-3","questionText":"What is the primary function of an operating system kernel?","options":[{"id":"soft-beg-3-d","label":"A","text":"To automatically download and install web browser security extensions from public software stores"},{"id":"soft-beg-3-c","label":"B","text":"To manage core hardware resources including CPU scheduling, memory allocation, and device I/O"},{"id":"soft-beg-3-a","label":"C","text":"To compile application source code into executable binary packages during software installation"},{"id":"soft-beg-3-b","label":"D","text":"To render graphical desktop windows, mouse pointers, and desktop background wallpapers"}],"correctOptionId":"soft-beg-3-c","difficulty":"beginner","complexity":"fundamental","conceptTag":"os-kernel-responsibilities","explanationAfterAnswer":"The kernel is the core of the operating system that has complete control over everything in the system, managing hardware resources (CPU, RAM, block storage, peripherals) and mediating software access via system calls.","questionNumber":3},{"id":"soft-beg-4","questionText":"In object-oriented programming, what does the concept of Encapsulation achieve?","options":[{"id":"soft-beg-4-a","label":"A","text":"Allowing a single child class to inherit property definitions simultaneously from multiple parent classes"},{"id":"soft-beg-4-c","label":"B","text":"Converting runtime memory data structures into static JSON files saved on persistent local hard drives"},{"id":"soft-beg-4-b","label":"C","text":"Automatically compiling source code into multiple distinct native operating system executable formats"},{"id":"soft-beg-4-d","label":"D","text":"Bundling data and methods within an object while hiding internal implementation details from external access"}],"correctOptionId":"soft-beg-4-d","difficulty":"beginner","complexity":"fundamental","conceptTag":"oop-encapsulation-principle","explanationAfterAnswer":"Encapsulation binds data and the methods that manipulate that data into a cohesive unit (class) while restricting direct external access to internal state, exposing only controlled public interfaces.","questionNumber":4},{"id":"soft-beg-5","questionText":"What is the primary operational purpose of unit testing in software development?","options":[{"id":"soft-beg-5-a","label":"A","text":"To test individual isolated functions or modules in isolation to ensure they produce expected outputs"},{"id":"soft-beg-5-d","label":"B","text":"To generate user documentation and API release notes automatically from database commit histories"},{"id":"soft-beg-5-b","label":"C","text":"To measure how many concurrent user requests a production database server can support before failure"},{"id":"soft-beg-5-c","label":"D","text":"To deploy compiled application binaries to cloud staging environments across multiple availability zones"}],"correctOptionId":"soft-beg-5-a","difficulty":"beginner","complexity":"fundamental","conceptTag":"unit-testing-fundamentals","explanationAfterAnswer":"Unit testing verifies that small, isolated pieces of code (functions, methods) work correctly given defined inputs, catching regressions early in development before integration.","questionNumber":5},{"id":"soft-beg-6","questionText":"A program enters an infinite recursion loop without a valid base case. What runtime error occurs?","options":[{"id":"soft-beg-6-a","label":"A","text":"A Segmentation Fault, caused by physical memory chips overheating due to excessive mathematical calculations"},{"id":"soft-beg-6-c","label":"B","text":"A Deadlock exception, because two background threads acquire mutual exclusion locks in conflicting order"},{"id":"soft-beg-6-d","label":"C","text":"A Null Pointer Dereference, because the operating system deletes unreferenced variables from heap storage"},{"id":"soft-beg-6-b","label":"D","text":"A Stack Overflow error, because recursive function call frames exhaust the allocated thread call stack memory"}],"correctOptionId":"soft-beg-6-b","difficulty":"beginner","complexity":"application","conceptTag":"recursion-stack-overflow","explanationAfterAnswer":"Each recursive call pushes a new stack frame (return address, arguments, local variables) onto the execution stack. Without a terminating base case, the stack exceeds its allocated memory limit, triggering a stack overflow.","questionNumber":6},{"id":"soft-beg-7","questionText":"Why do relational databases create B-Tree indexes on frequently queried table columns?","options":[{"id":"soft-beg-7-d","label":"A","text":"To automatically convert unstructured JSON payloads into normalized third normal form relations"},{"id":"soft-beg-7-b","label":"B","text":"To eliminate the need for primary key constraints and unique index definitions across related tables"},{"id":"soft-beg-7-a","label":"C","text":"To compress character string fields into binary format to minimize total hard drive storage usage"},{"id":"soft-beg-7-c","label":"D","text":"To allow the query optimizer to locate rows in logarithmic time O(log N) rather than scanning the full table"}],"correctOptionId":"soft-beg-7-c","difficulty":"beginner","complexity":"application","conceptTag":"database-btree-indexes","explanationAfterAnswer":"B-Tree indexes maintain sorted balanced trees of keys and row pointers, allowing search, range queries, and ordering in O(log N) disk reads, avoiding expensive O(N) full table scans.","questionNumber":7},{"id":"soft-beg-8","questionText":"In version control with Git, what is the effect of running `git checkout -b feature/login`?","options":[{"id":"soft-beg-8-a","label":"A","text":"It deletes the remote feature branch and reverts local tracked files to the previous commit state"},{"id":"soft-beg-8-b","label":"B","text":"It merges all commits from the ''feature/login'' branch into the main production branch automatically"},{"id":"soft-beg-8-c","label":"C","text":"It pushes all uncommitted local code changes directly to the remote repository on the central server"},{"id":"soft-beg-8-d","label":"D","text":"It creates a new branch named ''feature/login'' and immediately switches your working directory to it"}],"correctOptionId":"soft-beg-8-d","difficulty":"beginner","complexity":"application","conceptTag":"git-branching-workflow","explanationAfterAnswer":"The `-b` flag tells Git to create a new branch with the specified name and immediately switch the HEAD pointer and working tree to point to this new branch.","questionNumber":8},{"id":"soft-beg-9","questionText":"A sorting algorithm must guarantee stable sorting of records with identical keys. Which algorithm is naturally stable?","options":[{"id":"soft-beg-9-a","label":"A","text":"Merge Sort, which preserves the relative original input order of elements with equal key values"},{"id":"soft-beg-9-d","label":"B","text":"Selection Sort, which iteratively finds the minimum element and swaps it with the current position"},{"id":"soft-beg-9-b","label":"C","text":"Heap Sort, which organizes array values into binary max-heaps using non-adjacent element swaps"},{"id":"soft-beg-9-c","label":"D","text":"Quick Sort with in-place Lomuto partitioning, which swaps distant elements across pivot values"}],"correctOptionId":"soft-beg-9-a","difficulty":"beginner","complexity":"challenging","conceptTag":"sorting-algorithm-stability","explanationAfterAnswer":"A sorting algorithm is stable if it preserves the original relative order of records with equal keys. Merge Sort divides and merges subarrays while carefully prioritizing elements from the left subarray when keys match, preserving stability.","questionNumber":9},{"id":"soft-beg-10","questionText":"What is the primary memory management difference between Stack memory and Heap memory in compiled languages (e.g. C/Rust)?","options":[{"id":"soft-beg-10-d","label":"A","text":"Stack memory allows arbitrary runtime resizing of arrays, while Heap memory requires fixed compile-time sizes"},{"id":"soft-beg-10-b","label":"B","text":"Stack allocations are fast and automatically freed on function return, while Heap allocations are dynamic and persistent"},{"id":"soft-beg-10-c","label":"C","text":"Stack memory is stored on external persistent solid-state drives, while Heap memory resides in L1 cache"},{"id":"soft-beg-10-a","label":"D","text":"Stack memory stores global shared databases, while Heap memory stores local CPU instruction registers"}],"correctOptionId":"soft-beg-10-b","difficulty":"beginner","complexity":"challenging","conceptTag":"stack-vs-heap-memory","explanationAfterAnswer":"Stack memory is managed automatically by the CPU call stack; variables are pushed on function call and popped on return (very fast). Heap memory is allocated dynamically at runtime (malloc/new) and persists until explicitly freed or garbage-collected.","questionNumber":10}]'::jsonb, 10, '[{"questionId":"soft-beg-1","questionNumber":1,"selectedOptionId":"soft-beg-1-a","correctOptionId":"soft-beg-1-a","isCorrect":true,"timeSpentMs":5573,"conceptTag":"array-linear-search-complexity","complexity":"fundamental"},{"questionId":"soft-beg-2","questionNumber":2,"selectedOptionId":"soft-beg-2-b","correctOptionId":"soft-beg-2-b","isCorrect":true,"timeSpentMs":5241,"conceptTag":"stack-vs-queue-ordering","complexity":"fundamental"},{"questionId":"soft-beg-3","questionNumber":3,"selectedOptionId":"soft-beg-3-c","correctOptionId":"soft-beg-3-c","isCorrect":true,"timeSpentMs":4182,"conceptTag":"os-kernel-responsibilities","complexity":"fundamental"},{"questionId":"soft-beg-4","questionNumber":4,"selectedOptionId":"soft-beg-4-d","correctOptionId":"soft-beg-4-d","isCorrect":true,"timeSpentMs":11733,"conceptTag":"oop-encapsulation-principle","complexity":"fundamental"},{"questionId":"soft-beg-5","questionNumber":5,"selectedOptionId":"soft-beg-5-a","correctOptionId":"soft-beg-5-a","isCorrect":true,"timeSpentMs":6123,"conceptTag":"unit-testing-fundamentals","complexity":"fundamental"},{"questionId":"soft-beg-6","questionNumber":6,"selectedOptionId":"soft-beg-6-a","correctOptionId":"soft-beg-6-b","isCorrect":false,"timeSpentMs":16065,"conceptTag":"recursion-stack-overflow","complexity":"application"},{"questionId":"soft-beg-7","questionNumber":7,"selectedOptionId":"soft-beg-7-c","correctOptionId":"soft-beg-7-c","isCorrect":true,"timeSpentMs":4338,"conceptTag":"database-btree-indexes","complexity":"application"},{"questionId":"soft-beg-8","questionNumber":8,"selectedOptionId":"soft-beg-8-d","correctOptionId":"soft-beg-8-d","isCorrect":true,"timeSpentMs":13930,"conceptTag":"git-branching-workflow","complexity":"application"},{"questionId":"soft-beg-9","questionNumber":9,"selectedOptionId":"soft-beg-9-c","correctOptionId":"soft-beg-9-a","isCorrect":false,"timeSpentMs":1716,"conceptTag":"sorting-algorithm-stability","complexity":"challenging"},{"questionId":"soft-beg-10","questionNumber":10,"selectedOptionId":"soft-beg-10-a","correctOptionId":"soft-beg-10-b","isCorrect":false,"timeSpentMs":2380,"conceptTag":"stack-vs-heap-memory","complexity":"challenging"}]'::jsonb, 0, 'completed', '2026-09-06T11:25:23.815Z'::timestamptz, NULL, NULL)
