INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788777980241_0l9rh', '17752966-0044-48e3-b3aa-d1fe9caa76b3', 'security', 'Cybersecurity & Defenses', 'advanced', '[{"id":"sec-adv-1","questionText":"What underlying microarchitectural processor mechanism enables Spectre speculative execution side-channel attacks?","options":[{"id":"sec-adv-1-a","label":"A","text":"Branch predictors executing instructions speculatively past bounds checks and leaving cache timing traces"},{"id":"sec-adv-1-c","label":"B","text":"Hardware thermal throttling desynchronizing clock cycles between physical processor execution cores"},{"id":"sec-adv-1-b","label":"C","text":"Memory management unit page table fragmentation allowing unprivileged user space to read kernel frames"},{"id":"sec-adv-1-d","label":"D","text":"Improper cyclic redundancy checks on L1 data cache lines during asynchronous direct memory access"}],"correctOptionId":"sec-adv-1-a","difficulty":"advanced","complexity":"fundamental","conceptTag":"spectre-microarchitectural-flaw","explanationAfterAnswer":"Spectre exploits speculative execution where CPUs predict branch targets and execute code before bounds checks complete. When squashed, cache state changes persist and leak data via timing attacks.","questionNumber":1},{"id":"sec-adv-2","questionText":"In modern binary exploitation, what is the primary purpose of Return-Oriented Programming (ROP)?","options":[{"id":"sec-adv-2-a","label":"A","text":"To defeat Address Space Layout Randomization by brute-forcing fixed virtual memory offsets in running processes"},{"id":"sec-adv-2-d","label":"B","text":"To execute kernel shellcode by directly corrupting the hardware interrupt descriptor table from user space"},{"id":"sec-adv-2-b","label":"C","text":"To defeat Data Execution Prevention (W^X / DEP) by chaining existing executable instruction sequences ending in ret"},{"id":"sec-adv-2-c","label":"D","text":"To accelerate reverse engineering by translating raw assembly opcodes into structured control flow graphs"}],"correctOptionId":"sec-adv-2-b","difficulty":"advanced","complexity":"application","conceptTag":"rop-dep-bypass","explanationAfterAnswer":"When memory regions are marked non-executable (DEP/NX), ROP circumvents this by reusing existing snippets of executable binary code (''gadgets'') ending in return instructions to build arbitrary logic.","questionNumber":2},{"id":"sec-adv-3","questionText":"How is Kernel Address Space Layout Randomization (KASLR) typically defeated during exploit development?","options":[{"id":"sec-adv-3-b","label":"A","text":"By corrupting the system real-time clock to desynchronize kernel random number generator initialization"},{"id":"sec-adv-3-d","label":"B","text":"By modifying system security limits in user space configuration files to exceed kernel allocation limits"},{"id":"sec-adv-3-c","label":"C","text":"By using an information leak vulnerability that reveals a kernel pointer to calculate the randomized base offset"},{"id":"sec-adv-3-a","label":"D","text":"By transmitting high-volume ICMP echo requests to exhaust kernel socket buffer memory allocations"}],"correctOptionId":"sec-adv-3-c","difficulty":"advanced","complexity":"application","conceptTag":"kaslr-bypass-infoleak","explanationAfterAnswer":"KASLR randomizes the base memory location of kernel code. Attackers leverage an information disclosure bug that leaks a known kernel function pointer to calculate the base slide offset.","questionNumber":3},{"id":"sec-adv-4","questionText":"In Kubernetes, which container configuration enables an attacker to perform a host node breakout?","options":[{"id":"sec-adv-4-d","label":"A","text":"Running in privileged mode with hostPID and hostNetwork enabled or the host filesystem mounted read-write"},{"id":"sec-adv-4-b","label":"B","text":"Attaching a Horizontal Pod Autoscaler that adjusts pod replica counts based on CPU utilization metrics"},{"id":"sec-adv-4-c","label":"C","text":"Deploying a container image built on minimal Alpine Linux rather than an enterprise Linux distribution"},{"id":"sec-adv-4-a","label":"D","text":"Configuring the pod to resolve DNS through cluster CoreDNS services rather than node-local caching daemons"}],"correctOptionId":"sec-adv-4-d","difficulty":"advanced","complexity":"application","conceptTag":"container-escape-privilege","explanationAfterAnswer":"Privileged containers disable Linux cgroup and namespace isolation. Access to host devices or the root filesystem allows escape via chroot, device access, or cgroup release agent manipulation.","questionNumber":4},{"id":"sec-adv-5","questionText":"What condition permits an attacker to perform a Blind Time-Based SQL Injection attack against an API?","options":[{"id":"sec-adv-5-b","label":"A","text":"The database server exposes detailed error stack traces and internal schema definitions in HTTP 500 responses"},{"id":"sec-adv-5-d","label":"B","text":"The application communicates with the database over an unencrypted network connection without TLS verification"},{"id":"sec-adv-5-c","label":"C","text":"The database connection pool suffers from connection starvation due to unindexed queries on large tables"},{"id":"sec-adv-5-a","label":"D","text":"The endpoint returns identical responses regardless of query results, but evaluates injected delay functions"}],"correctOptionId":"sec-adv-5-a","difficulty":"advanced","complexity":"challenging","conceptTag":"blind-time-based-sqli","explanationAfterAnswer":"When an application leaks no data or differential error messages, an attacker injects conditional time-delay commands (like pg_sleep or WAITFOR DELAY) to infer data bit-by-bit from response times.","questionNumber":5},{"id":"sec-adv-6","questionText":"In SAML 2.0 implementations, what design flaw enables XML Signature Wrapping (XSW) attacks?","options":[{"id":"sec-adv-6-a","label":"A","text":"A mismatch between the XML structure used during signature canonicalization and that interpreted by the app"},{"id":"sec-adv-6-c","label":"B","text":"A mismatch between namespace resolution during signature verification and resolution during assertion processing"},{"id":"sec-adv-6-b","label":"C","text":"A mismatch between the XML node validated by the signature verifier and the node consumed by business logic"},{"id":"sec-adv-6-d","label":"D","text":"A mismatch between schema validation of the assertion and resolution of referenced signed element identifiers"}],"correctOptionId":"sec-adv-6-b","difficulty":"advanced","complexity":"challenging","conceptTag":"saml-xml-signature-wrapping","explanationAfterAnswer":"XSW exploits architectural discrepancies where signature verification validates an intact assertion, while business logic retrieves user claims from an unsigned, wrapped element elsewhere in the DOM.","questionNumber":6},{"id":"sec-adv-7","questionText":"What cryptographic flaw made WPA2''s 4-way handshake vulnerable to Key Reinstallation Attacks (KRACK)?","options":[{"id":"sec-adv-7-c","label":"A","text":"The client reinstalling an in-use pairwise key upon receiving retransmitted Message 3, resetting the packet counter"},{"id":"sec-adv-7-d","label":"B","text":"The wireless controller generating predictable initialization vectors during RC4 stream cipher encapsulation"},{"id":"sec-adv-7-a","label":"C","text":"The access point using weak Diffie-Hellman primes that allow pre-computation attacks against session keys"},{"id":"sec-adv-7-b","label":"D","text":"The authentication server transmitting the master pre-shared key in plaintext beacon frames during discovery"}],"correctOptionId":"sec-adv-7-c","difficulty":"advanced","complexity":"challenging","conceptTag":"krack-wpa2-handshake","explanationAfterAnswer":"KRACK exploits Message 3 retransmission. When re-received, vulnerable clients reinstall the already active PTK and reset its transmit replay counter (nonce), enabling keystream reuse attacks.","questionNumber":7},{"id":"sec-adv-8","questionText":"Why is ML-KEM (Kyber) categorized as lattice-based post-quantum cryptography?","options":[{"id":"sec-adv-8-c","label":"A","text":"It generates symmetric one-time pads derived from cosmic background radiation sensors embedded in security modules"},{"id":"sec-adv-8-b","label":"B","text":"It utilizes super-singular elliptic curve isogenies requiring exponential classical resources to compute path morphisms"},{"id":"sec-adv-8-d","label":"C","text":"Its security relies on high-dimensional lattice vector problems that cannot be solved efficiently by Shor''s algorithm"},{"id":"sec-adv-8-a","label":"D","text":"It employs quantum key distribution channels that leverage photon entanglement to detect eavesdropping on optical lines"}],"correctOptionId":"sec-adv-8-d","difficulty":"advanced","complexity":"challenging","conceptTag":"post-quantum-lattice-crypto","explanationAfterAnswer":"ML-KEM security reduces to the Module Learning with Errors (M-LWE) problem over high-dimensional lattices, which resists both classical algorithms and quantum attacks based on Shor''s algorithm.","questionNumber":8},{"id":"sec-adv-9","questionText":"In eBPF security observability tooling, how can a root-privileged adversary attempt to blind kernel telemetry?","options":[{"id":"sec-adv-9-a","label":"A","text":"By detaching kernel tracepoints via bpf syscalls or flooding the ring buffer to induce massive unlogged event drops"},{"id":"sec-adv-9-b","label":"B","text":"By modifying userspace /etc/resolv.conf configuration files to redirect internal DNS queries to external resolvers"},{"id":"sec-adv-9-c","label":"C","text":"By installing unapproved compilers on the host worker node to trigger local static binary analysis warnings"},{"id":"sec-adv-9-d","label":"D","text":"By adjusting system timezone configurations to create clock drift between worker nodes and the control plane"}],"correctOptionId":"sec-adv-9-a","difficulty":"advanced","complexity":"challenging","conceptTag":"ebpf-telemetry-evasion","explanationAfterAnswer":"An adversary with root or CAP_BPF can interact directly with the bpf() syscall to detach attached probes, corrupt BPF maps, or generate high-volume synthetic events to overflow ring buffers.","questionNumber":9},{"id":"sec-adv-10","questionText":"Which defense mechanism specifically protects cloud instance metadata endpoints (169.254.169.254) against SSRF?","options":[{"id":"sec-adv-10-a","label":"A","text":"Configuring public DNS records to map internal private IP subnets to corporate reverse proxy load balancers"},{"id":"sec-adv-10-d","label":"B","text":"Enforcing multi-factor authentication on all administrative SSH connections established to worker compute nodes"},{"id":"sec-adv-10-b","label":"C","text":"Enforcing IMDSv2 requiring session-oriented PUT requests with signed token headers alongside strict egress filtering"},{"id":"sec-adv-10-c","label":"D","text":"Encoding all outbound HTTP request bodies into base64 strings before transmitting them over network gateways"}],"correctOptionId":"sec-adv-10-b","difficulty":"advanced","complexity":"challenging","conceptTag":"imdsv2-ssrf-mitigation","explanationAfterAnswer":"IMDSv2 requires clients to first execute a PUT request to generate a session token (which standard SSRF vectors cannot easily forge) before querying metadata, and sets token hop limits to block proxies.","questionNumber":10}]'::jsonb, 0, '[]'::jsonb, 0, 'completed', '2026-09-07T10:46:20.241Z'::timestamptz, NULL, NULL)
