  answers = EXCLUDED.answers,
  time_remaining_seconds = EXCLUDED.time_remaining_seconds,
  status = EXCLUDED.status,
  completed_at = EXCLUDED.completed_at;
INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788778518632_94fmx', '47fc1671-0e5d-4f66-af79-ca34f5e10ec5', 'security', 'Cybersecurity & Defense', 'beginner', '[{"id":"sec-beg-1","questionText":"What is the primary role of a network firewall in an IT infrastructure?","options":[{"id":"sec-beg-1-a","label":"A","text":"To inspect and control incoming and outgoing network traffic based on predefined security rules"},{"id":"sec-beg-1-d","label":"B","text":"To dynamically assign IP configurations and DNS gateway addresses to connecting client hosts"},{"id":"sec-beg-1-c","label":"C","text":"To establish encrypted point-to-point tunnels between remote branch offices and corporate data centers"},{"id":"sec-beg-1-b","label":"D","text":"To translate private internal IP addresses to routable external addresses across corporate subnets"}],"correctOptionId":"sec-beg-1-a","difficulty":"beginner","complexity":"fundamental","conceptTag":"firewall-basics","explanationAfterAnswer":"A firewall monitors and filters network traffic based on configured security policies, establishing a security boundary between trusted internal networks and untrusted external networks.","questionNumber":1},{"id":"sec-beg-2","questionText":"Which of the following best describes Multi-Factor Authentication (MFA)?","options":[{"id":"sec-beg-2-d","label":"A","text":"Authenticating client requests through sequential cryptographic handshakes across border gateway proxies"},{"id":"sec-beg-2-a","label":"B","text":"Requiring two independent system administrators to concurrently approve every interactive user session"},{"id":"sec-beg-2-b","label":"C","text":"Verifying identity using credentials from two or more distinct categories such as passwords and security keys"},{"id":"sec-beg-2-c","label":"D","text":"Enforcing periodic passphrase rotations combining numbers, symbols, uppercase letters, and minimum length"}],"correctOptionId":"sec-beg-2-b","difficulty":"beginner","complexity":"fundamental","conceptTag":"mfa-principles","explanationAfterAnswer":"MFA requires two or more distinct categories of credentials: something you know (password), something you have (security key or authenticator app), or something you are (biometrics).","questionNumber":2},{"id":"sec-beg-3","questionText":"What distinguishes symmetric encryption from asymmetric encryption?","options":[{"id":"sec-beg-3-b","label":"A","text":"Symmetric requires dedicated hardware security modules, while asymmetric executes entirely in memory"},{"id":"sec-beg-3-d","label":"B","text":"Symmetric is restricted to static data at rest, while asymmetric is exclusively deployed for data in transit"},{"id":"sec-beg-3-a","label":"C","text":"Symmetric uses one-way hash transformations without reversal, while asymmetric enables two-way data recovery"},{"id":"sec-beg-3-c","label":"D","text":"Symmetric uses a single shared key for encryption and decryption, while asymmetric uses a public-private key pair"}],"correctOptionId":"sec-beg-3-c","difficulty":"beginner","complexity":"fundamental","conceptTag":"encryption-fundamentals","explanationAfterAnswer":"Symmetric encryption (such as AES) uses the same secret key for encryption and decryption. Asymmetric encryption (such as RSA or ECC) uses mathematically linked public and private key pairs.","questionNumber":3},{"id":"sec-beg-4","questionText":"Which social engineering attack tricks victims into revealing credentials through deceptive communications?","options":[{"id":"sec-beg-4-b","label":"A","text":"A watering hole attack compromising legitimate websites regularly frequented by target personnel"},{"id":"sec-beg-4-d","label":"B","text":"A phishing attack delivering fraudulent messages designed to deceive recipients into disclosing credentials"},{"id":"sec-beg-4-c","label":"C","text":"A man-in-the-middle attack intercepting unencrypted transport layer communication across public networks"},{"id":"sec-beg-4-a","label":"D","text":"A credential stuffing attack testing breached credential lists against target authentication endpoints"}],"correctOptionId":"sec-beg-4-d","difficulty":"beginner","complexity":"fundamental","conceptTag":"social-engineering-phishing","explanationAfterAnswer":"Phishing uses deceptive emails, messages, or websites masquerading as trustworthy entities to trick individuals into disclosing sensitive information such as login credentials.","questionNumber":4},{"id":"sec-beg-5","questionText":"What does the ''A'' represent in the CIA triad of information security?","options":[{"id":"sec-beg-5-b","label":"A","text":"Authentication, verifying the claimed identity of a user or system before granting access permissions"},{"id":"sec-beg-5-c","label":"B","text":"Authorization, determining the specific access privileges and permissions granted to a verified identity"},{"id":"sec-beg-5-a","label":"C","text":"Availability, ensuring authorized users have timely and reliable access to critical systems and data"},{"id":"sec-beg-5-d","label":"D","text":"Accountability, maintaining audit logs to trace actions and system events back to individual user sessions"}],"correctOptionId":"sec-beg-5-a","difficulty":"beginner","complexity":"fundamental","conceptTag":"cia-triad","explanationAfterAnswer":"The CIA triad consists of Confidentiality (preventing unauthorized disclosure), Integrity (preventing unauthorized modification), and Availability (ensuring accessible, reliable service).","questionNumber":5},{"id":"sec-beg-6","questionText":"An employee receives an urgent message appearing to come from an executive. What is the best immediate response?","options":[{"id":"sec-beg-6-b","label":"A","text":"Verify the authenticity of the request through an independent, pre-established communication channel"},{"id":"sec-beg-6-d","label":"B","text":"Inspect the email header routing trail to verify whether SPF and DKIM pass checks were recorded"},{"id":"sec-beg-6-c","label":"C","text":"Reply directly to the email requesting secondary identity confirmation and digital signature verification"},{"id":"sec-beg-6-a","label":"D","text":"Forward the suspicious message to the corporate email administrator to block the sending domain"}],"correctOptionId":"sec-beg-6-b","difficulty":"beginner","complexity":"application","conceptTag":"phishing-mitigation","explanationAfterAnswer":"Executive impersonation exploits urgency and authority. The standard defense is out-of-band verification using a trusted, independent communication channel such as an internal phone directory.","questionNumber":6},{"id":"sec-beg-7","questionText":"Why should web applications never store user passwords in plaintext inside databases?","options":[{"id":"sec-beg-7-b","label":"A","text":"Plaintext passwords violate database syntax standards by storing unhashed character data in table fields"},{"id":"sec-beg-7-d","label":"B","text":"Plaintext passwords prevent authentication microservices from caching user login tokens efficiently"},{"id":"sec-beg-7-c","label":"C","text":"Plaintext passwords expose all user credentials immediately if the database storage layer is compromised"},{"id":"sec-beg-7-a","label":"D","text":"Plaintext passwords cause relational indexing fragmentation during high-volume database queries"}],"correctOptionId":"sec-beg-7-c","difficulty":"beginner","complexity":"application","conceptTag":"password-storage-safety","explanationAfterAnswer":"Plaintext storage guarantees full account compromise if database dumps or backups are leaked. Passwords must be hashed using salted, adaptive algorithms like bcrypt or Argon2.","questionNumber":7},{"id":"sec-beg-8","questionText":"What does the padlock icon and HTTPS in a web browser''s address bar signify?","options":[{"id":"sec-beg-8-d","label":"A","text":"Traffic between the browser and web server is encrypted and protected against eavesdropping via TLS"},{"id":"sec-beg-8-b","label":"B","text":"The web host''s physical data center possesses verified enterprise compliance security certifications"},{"id":"sec-beg-8-a","label":"C","text":"The destination website is certified free of application vulnerabilities and malware infections"},{"id":"sec-beg-8-c","label":"D","text":"The website operator has been cryptographically vetted by the operating system vendor"}],"correctOptionId":"sec-beg-8-d","difficulty":"beginner","complexity":"application","conceptTag":"tls-transport-security","explanationAfterAnswer":"HTTPS confirms transport-layer encryption via TLS, ensuring data confidentiality and integrity between client and server. It does not verify the security of the backend application itself.","questionNumber":8},{"id":"sec-beg-9","questionText":"Which method provides the most effective protection for an enterprise wireless network?","options":[{"id":"sec-beg-9-b","label":"A","text":"Suppressing the wireless SSID beacon broadcast to hide the network name from nearby mobile scanning tools"},{"id":"sec-beg-9-d","label":"B","text":"Configuring WPA2-PSK with a complex shared passphrase distributed to all corporate staff members"},{"id":"sec-beg-9-a","label":"C","text":"Deploying WPA3 Enterprise with 802.1X certificate-based individual authentication per connecting device"},{"id":"sec-beg-9-c","label":"D","text":"Restricting network access by configuring static MAC address filtering on wireless access controllers"}],"correctOptionId":"sec-beg-9-a","difficulty":"beginner","complexity":"challenging","conceptTag":"wireless-network-hardening","explanationAfterAnswer":"WPA3 Enterprise with 802.1X provides individual credentials and mutual certificate authentication, preventing credential sharing and rogue access point spoofing.","questionNumber":9},{"id":"sec-beg-10","questionText":"What risk arises from leaving default administrative credentials on newly installed network switches?","options":[{"id":"sec-beg-10-b","label":"A","text":"Automated scanning tools exploit known vendor credentials to gain unauthorized administrative access"},{"id":"sec-beg-10-c","label":"B","text":"Internal hardware diagnostics fail to initialize packet forwarding buffers across Gigabit Ethernet ports"},{"id":"sec-beg-10-d","label":"C","text":"The network switch automatically reverts to unmanaged hub mode after forty-eight hours of uptime"},{"id":"sec-beg-10-a","label":"D","text":"Network routing switches throttle bandwidth allocation to prevent unverified firmware execution"}],"correctOptionId":"sec-beg-10-b","difficulty":"beginner","complexity":"challenging","conceptTag":"default-credentials-risk","explanationAfterAnswer":"Factory default credentials are systematically cataloged in publicly available threat databases and targeted by automated scanners within minutes of network exposure.","questionNumber":10}]'::jsonb, 10, '[{"questionId":"sec-beg-1","questionNumber":1,"selectedOptionId":"sec-beg-1-a","correctOptionId":"sec-beg-1-a","isCorrect":true,"timeSpentMs":32570,"conceptTag":"firewall-basics","complexity":"fundamental"},{"questionId":"sec-beg-2","questionNumber":2,"selectedOptionId":"sec-beg-2-d","correctOptionId":"sec-beg-2-b","isCorrect":false,"timeSpentMs":10693,"conceptTag":"mfa-principles","complexity":"fundamental"},{"questionId":"sec-beg-3","questionNumber":3,"selectedOptionId":"sec-beg-3-c","correctOptionId":"sec-beg-3-c","isCorrect":true,"timeSpentMs":15504,"conceptTag":"encryption-fundamentals","complexity":"fundamental"},{"questionId":"sec-beg-4","questionNumber":4,"selectedOptionId":"sec-beg-4-d","correctOptionId":"sec-beg-4-d","isCorrect":true,"timeSpentMs":6266,"conceptTag":"social-engineering-phishing","complexity":"fundamental"},{"questionId":"sec-beg-5","questionNumber":5,"selectedOptionId":"sec-beg-5-a","correctOptionId":"sec-beg-5-a","isCorrect":true,"timeSpentMs":8003,"conceptTag":"cia-triad","complexity":"fundamental"},{"questionId":"sec-beg-6","questionNumber":6,"selectedOptionId":"sec-beg-6-b","correctOptionId":"sec-beg-6-b","isCorrect":true,"timeSpentMs":16171,"conceptTag":"phishing-mitigation","complexity":"application"},{"questionId":"sec-beg-7","questionNumber":7,"selectedOptionId":"sec-beg-7-c","correctOptionId":"sec-beg-7-c","isCorrect":true,"timeSpentMs":15744,"conceptTag":"password-storage-safety","complexity":"application"},{"questionId":"sec-beg-8","questionNumber":8,"selectedOptionId":"sec-beg-8-b","correctOptionId":"sec-beg-8-d","isCorrect":false,"timeSpentMs":6276,"conceptTag":"tls-transport-security","complexity":"application"},{"questionId":"sec-beg-9","questionNumber":9,"selectedOptionId":"sec-beg-9-c","correctOptionId":"sec-beg-9-a","isCorrect":false,"timeSpentMs":7993,"conceptTag":"wireless-network-hardening","complexity":"challenging"},{"questionId":"sec-beg-10","questionNumber":10,"selectedOptionId":"sec-beg-10-b","correctOptionId":"sec-beg-10-b","isCorrect":true,"timeSpentMs":5428,"conceptTag":"default-credentials-risk","complexity":"challenging"}]'::jsonb, 0, 'completed', '2026-09-07T10:55:18.632Z'::timestamptz, NULL, NULL)
