INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788779562182_koh0v', '43a69d7a-8521-41eb-ade3-8659f17099e2', 'security', 'Cybersecurity & Defenses', 'intermediate', '[{"id":"sec-int-1","questionText":"How does a Cross-Site Scripting (XSS) attack execute in a target web application?","options":[{"id":"sec-int-1-c","label":"A","text":"By injecting untrusted client script into web application pages that executes in other users'' browsers"},{"id":"sec-int-1-d","label":"B","text":"By corrupting browser DNS cache records to redirect legitimate API requests to adversary endpoints"},{"id":"sec-int-1-b","label":"C","text":"By appending SQL syntax into URL parameters to dump user password hashes from the relational database"},{"id":"sec-int-1-a","label":"D","text":"By manipulating HTTP caching headers to store sensitive authentication cookies in intermediate proxies"}],"correctOptionId":"sec-int-1-c","difficulty":"intermediate","complexity":"fundamental","conceptTag":"xss-vulnerability-mechanism","explanationAfterAnswer":"XSS occurs when an application includes untrusted user input without context-aware encoding, leading the browser to execute injected scripts in the security context of the user.","questionNumber":1},{"id":"sec-int-2","questionText":"Which HTTP header is specifically designed to restrict where scripts, styles, and assets can load from?","options":[{"id":"sec-int-2-b","label":"A","text":"X-Frame-Options, preventing malicious sites from rendering the target page inside hidden frame overlays"},{"id":"sec-int-2-d","label":"B","text":"Content-Security-Policy (CSP), declaring authorized sources from which scripts and resources may be loaded"},{"id":"sec-int-2-a","label":"C","text":"Strict-Transport-Security (HSTS), enforcing encrypted HTTPS communication for all domain connections"},{"id":"sec-int-2-c","label":"D","text":"Access-Control-Allow-Origin, controlling which external web domains can access cross-origin API responses"}],"correctOptionId":"sec-int-2-d","difficulty":"intermediate","complexity":"fundamental","conceptTag":"csp-security-headers","explanationAfterAnswer":"Content-Security-Policy (CSP) allows site operators to restrict the origins of executable scripts, stylesheets, and media, effectively neutralizing unauthorized inline script execution.","questionNumber":2},{"id":"sec-int-3","questionText":"Why are adaptive algorithms like Argon2 and bcrypt preferred over fast hashes like SHA-256 for passwords?","options":[{"id":"sec-int-3-c","label":"A","text":"They use asymmetric key pairs requiring separate public and private keys to verify password matches"},{"id":"sec-int-3-b","label":"B","text":"They generate variable-length outputs that eliminate hash collision vulnerabilities across large datasets"},{"id":"sec-int-3-a","label":"C","text":"They incorporate configurable work factors and memory hardness to resist GPU and ASIC brute-force attacks"},{"id":"sec-int-3-d","label":"D","text":"They eliminate the need for random cryptographic salts by computing deterministic seed values"}],"correctOptionId":"sec-int-3-a","difficulty":"intermediate","complexity":"fundamental","conceptTag":"adaptive-password-hashing","explanationAfterAnswer":"Fast hash functions like SHA-256 are engineered for speed, allowing billions of guesses per second on GPUs. Adaptive functions introduce computational work factors and memory demands to thwart hardware cracking.","questionNumber":3},{"id":"sec-int-4","questionText":"A security analyst observes high volumes of outbound DNS queries for random hex subdomains. What is the threat?","options":[{"id":"sec-int-4-d","label":"A","text":"Dynamic DNS client registration updating external public IP address bindings following lease renewal"},{"id":"sec-int-4-c","label":"B","text":"Authoritative name server zone synchronization transferring DNS resource records to secondary servers"},{"id":"sec-int-4-b","label":"C","text":"DNS tunneling and data exfiltration encoding unauthorized data within sequential lookup query labels"},{"id":"sec-int-4-a","label":"D","text":"Standard browser cache prefetching optimizing domain name resolution latency for anticipated user clicks"}],"correctOptionId":"sec-int-4-b","difficulty":"intermediate","complexity":"application","conceptTag":"dns-tunneling-exfiltration","explanationAfterAnswer":"DNS tunneling encapsulates non-DNS traffic or stolen data inside DNS queries (e.g. data.attacker.com), bypassing standard egress firewall rules that leave port 53 open.","questionNumber":4},{"id":"sec-int-5","questionText":"What is the most robust defense against SQL Injection vulnerabilities in modern web applications?","options":[{"id":"sec-int-5-a","label":"A","text":"Filtering incoming request parameters with regular expressions to remove single quotes and semicolons"},{"id":"sec-int-5-b","label":"B","text":"Storing database credentials in encrypted configuration files rather than hardcoding them in source"},{"id":"sec-int-5-d","label":"C","text":"Restricting database connections to communicate exclusively over mutually authenticated TLS sockets"},{"id":"sec-int-5-c","label":"D","text":"Using parameterized queries (prepared statements) that separate user input from SQL command structure"}],"correctOptionId":"sec-int-5-c","difficulty":"intermediate","complexity":"application","conceptTag":"parameterized-queries-sqli","explanationAfterAnswer":"Parameterized queries ensure the database driver treats user input strictly as data values, preventing user input from altering the compiled SQL query syntax.","questionNumber":5},{"id":"sec-int-6","questionText":"What security advantage does network micro-segmentation provide inside a corporate infrastructure?","options":[{"id":"sec-int-6-c","label":"A","text":"It automates edge router failover by dynamically re-routing external traffic across redundant gateways"},{"id":"sec-int-6-a","label":"B","text":"It increases raw packet throughput by bypassing perimeter firewall inspection for internal subnet traffic"},{"id":"sec-int-6-b","label":"C","text":"It removes the operational requirement to apply operating system security updates on internal servers"},{"id":"sec-int-6-d","label":"D","text":"It isolates workloads into discrete zones, preventing adversaries from moving laterally if a host is breached"}],"correctOptionId":"sec-int-6-d","difficulty":"intermediate","complexity":"application","conceptTag":"network-microsegmentation","explanationAfterAnswer":"Micro-segmentation restricts communication between workloads according to granular policies, limiting an attacker''s ability to move laterally across an internal network.","questionNumber":6},{"id":"sec-int-7","questionText":"If an API verifies JWTs without enforcing the signature algorithm (accepting ''alg: none''), what attack occurs?","options":[{"id":"sec-int-7-d","label":"A","text":"Attackers can force identity servers to issue refresh tokens with permanent operational validity periods"},{"id":"sec-int-7-b","label":"B","text":"Attackers can cause server denial of service by triggering recursive cryptographic verification routines"},{"id":"sec-int-7-c","label":"C","text":"Attackers can bypass Cross-Origin Resource Sharing (CORS) preflight validation on protected endpoints"},{"id":"sec-int-7-a","label":"D","text":"Attackers can forge arbitrary claims and tamper with tokens without needing a valid cryptographic signature"}],"correctOptionId":"sec-int-7-a","difficulty":"intermediate","complexity":"application","conceptTag":"jwt-none-algorithm-flaw","explanationAfterAnswer":"If a server blindly honors ''alg: none'', an attacker can modify the token payload (e.g. elevating role to admin) and strip the signature, gaining unauthorized privileges.","questionNumber":7},{"id":"sec-int-8","questionText":"What is the primary security goal of implementing the Principle of Least Privilege (PoLP)?","options":[{"id":"sec-int-8-d","label":"A","text":"To enforce automatic session logout whenever an authenticated user remains inactive for fifteen minutes"},{"id":"sec-int-8-a","label":"B","text":"To reduce cloud infrastructure billing costs by removing unused role-based access control assignments"},{"id":"sec-int-8-c","label":"C","text":"To eliminate the need for administrative accounts by delegating all operational tasks to background services"},{"id":"sec-int-8-b","label":"D","text":"To restrict user and process permissions strictly to what is necessary, minimizing potential blast radius"}],"correctOptionId":"sec-int-8-b","difficulty":"intermediate","complexity":"challenging","conceptTag":"least-privilege-principle","explanationAfterAnswer":"Least Privilege dictates that users, processes, and systems should hold only the bare minimum permissions required to perform their functions, containing damage from compromise.","questionNumber":8},{"id":"sec-int-9","questionText":"How does Online Certificate Status Protocol (OCSP) Stapling improve upon traditional revocation checking?","options":[{"id":"sec-int-9-d","label":"A","text":"It replaces asymmetric public key infrastructure with symmetric shared secret keys across web browsers"},{"id":"sec-int-9-b","label":"B","text":"It embeds the revocation status of all public certificates directly into local operating system trust stores"},{"id":"sec-int-9-c","label":"C","text":"It allows web servers to deliver timestamped, CA-signed revocation proof during the TLS handshake"},{"id":"sec-int-9-a","label":"D","text":"It allows web clients to query multiple Certificate Authorities concurrently to verify root trust chains"}],"correctOptionId":"sec-int-9-c","difficulty":"intermediate","complexity":"challenging","conceptTag":"ocsp-stapling-pki","explanationAfterAnswer":"OCSP Stapling delegates status retrieval to the web server, which caches a signed OCSP response and presents it to connecting clients during TLS negotiation, enhancing speed and privacy.","questionNumber":9},{"id":"sec-int-10","questionText":"Which defense effectively prevents Cross-Site Request Forgery (CSRF) on state-changing web endpoints?","options":[{"id":"sec-int-10-a","label":"A","text":"Restricting all backend database transactions to execute in read-only mode for unauthenticated client sessions"},{"id":"sec-int-10-d","label":"B","text":"Validating unpredictable anti-CSRF tokens and using SameSite cookie flags on state-changing requests"},{"id":"sec-int-10-b","label":"C","text":"Encoding all incoming form parameters into base64 strings before processing them in application controllers"},{"id":"sec-int-10-c","label":"D","text":"Mandating password complexity rules that enforce credential changes every thirty days for active users"}],"correctOptionId":"sec-int-10-d","difficulty":"intermediate","complexity":"challenging","conceptTag":"csrf-mitigation-tokens","explanationAfterAnswer":"CSRF protection requires unpredictable anti-CSRF tokens tied to the user''s session that third-party sites cannot read or guess, alongside SameSite cookie attributes.","questionNumber":10}]'::jsonb, 0, '[]'::jsonb, 0, 'completed', '2026-09-07T11:12:42.182Z'::timestamptz, NULL, NULL)
