  completed_at = EXCLUDED.completed_at;
INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788779647732_bw4m9', '2e6e232a-c966-4803-b87d-6f41a6be1a7a', 'web', 'Full-Stack Development', 'intermediate', '[{"id":"web-int-1","questionText":"How does the JavaScript Event Loop coordinate the execution of microtasks (Promises) versus macrotasks (setTimeout)?","options":[{"id":"web-int-1-d","label":"A","text":"Microtasks are cancelled automatically if a new macrotask arrives in the queue within five milliseconds"},{"id":"web-int-1-b","label":"B","text":"Microtasks execute after all pending macrotasks finish, right before the browser rendering frame begins"},{"id":"web-int-1-c","label":"C","text":"Macrotasks and microtasks execute concurrently on separate operating system background threads"},{"id":"web-int-1-a","label":"D","text":"The microtask queue is completely drained after each synchronous call stack completion before the next macrotask runs"}],"correctOptionId":"web-int-1-a","difficulty":"intermediate","complexity":"fundamental","conceptTag":"event-loop-microtasks","explanationAfterAnswer":"At the end of each task on the call stack, the JavaScript runtime completely exhausts the microtask queue (Promise callbacks, queueMicrotask, MutationObservers) before picking the next macrotask (setTimeout, I/O).","questionNumber":1},{"id":"web-int-2","questionText":"In React, what problem does the useCallback hook specifically solve?","options":[{"id":"web-int-2-d","label":"A","text":"It converts client component state mutations into server actions executed directly on backend workers"},{"id":"web-int-2-b","label":"B","text":"It memoizes a callback function definition between renders, maintaining reference equality for optimized child components"},{"id":"web-int-2-c","label":"C","text":"It automatically captures unhandled JavaScript runtime exceptions thrown during component render lifecycles"},{"id":"web-int-2-a","label":"D","text":"It memoizes heavy synchronous computational calculations to prevent them from executing on the main thread"}],"correctOptionId":"web-int-2-b","difficulty":"intermediate","complexity":"fundamental","conceptTag":"react-usecallback-memoization","explanationAfterAnswer":"In React, functions are recreated on every render. useCallback memoizes the function instance based on a dependency array, preserving reference equality (===) so that child components wrapped in React.memo skip unnecessary re-renders.","questionNumber":2},{"id":"web-int-3","questionText":"What distinguishes Server-Side Rendering (SSR) from Static Site Generation (SSG) in frameworks like Next.js?","options":[{"id":"web-int-3-b","label":"A","text":"SSR eliminates the need for client hydration, while SSG requires downloading complete server database drivers"},{"id":"web-int-3-c","label":"B","text":"SSR renders HTML dynamically on each user request, while SSG pre-renders HTML pages ahead of time at build time"},{"id":"web-int-3-d","label":"C","text":"SSR cannot fetch data from external REST APIs, while SSG dynamically connects to live WebSocket feeds"},{"id":"web-int-3-a","label":"D","text":"SSR is executed inside the user''s browser, while SSG requires continuous Node.js server runtimes in production"}],"correctOptionId":"web-int-3-c","difficulty":"intermediate","complexity":"fundamental","conceptTag":"ssr-vs-ssg-rendering","explanationAfterAnswer":"SSR generates HTML dynamically per request on the server (suitable for personalized, real-time data). SSG generates HTML once during compilation, allowing pages to be cached globally on CDNs for near-instant delivery.","questionNumber":3},{"id":"web-int-4","questionText":"How does Cross-Origin Resource Sharing (CORS) evaluate whether a cross-origin HTTP request is permitted?","options":[{"id":"web-int-4-c","label":"A","text":"The web server forces the connecting client browser to restart and clear all stored session cookies"},{"id":"web-int-4-a","label":"B","text":"The client browser verifies that the destination server IP address belongs to the same local subnet range"},{"id":"web-int-4-d","label":"C","text":"The browser sends an OPTIONS preflight request to verify that server response headers allow the origin and method"},{"id":"web-int-4-b","label":"D","text":"The operating system firewall inspects the application process signature against global DNS records"}],"correctOptionId":"web-int-4-d","difficulty":"intermediate","complexity":"application","conceptTag":"cors-preflight-mechanics","explanationAfterAnswer":"For non-simple requests, browsers dispatch an HTTP OPTIONS preflight call with Origin and Access-Control-Request-* headers. The browser checks if the server responds with Access-Control-Allow-Origin matching the calling domain before proceeding.","questionNumber":4},{"id":"web-int-5","questionText":"An e-commerce search bar triggers an API call on every keystroke, causing severe backend query overload. What is the solution?","options":[{"id":"web-int-5-b","label":"A","text":"Convert all search queries into synchronous XMLHttpRequest calls executed directly on the main thread"},{"id":"web-int-5-c","label":"B","text":"Store the entire product catalog database in the user''s browser cookie storage header partition"},{"id":"web-int-5-d","label":"C","text":"Disable browser JavaScript and force the search input to submit a standard multi-part form post"},{"id":"web-int-5-a","label":"D","text":"Implement a debounce function that waits for the user to pause typing before dispatching the network request"}],"correctOptionId":"web-int-5-a","difficulty":"intermediate","complexity":"application","conceptTag":"debounce-vs-throttle","explanationAfterAnswer":"Debouncing delays the function execution until a specified delay has elapsed since the last event (e.g. 300ms after user stops typing). This collapses 20 rapid keystrokes into a single optimized network query.","questionNumber":5},{"id":"web-int-6","questionText":"What role does optimistic UI update play in modern full-stack web applications?","options":[{"id":"web-int-6-d","label":"A","text":"It forces the client browser to refresh the entire webpage immediately following every user interaction"},{"id":"web-int-6-a","label":"B","text":"It caches all user modifications on the server for twenty-four hours before committing them to the database"},{"id":"web-int-6-b","label":"C","text":"It updates the client interface immediately assuming the mutation succeeds, rolling back if the server fails"},{"id":"web-int-6-c","label":"D","text":"It converts frontend state changes into binary WebAssembly instructions to bypass network validation"}],"correctOptionId":"web-int-6-b","difficulty":"intermediate","complexity":"application","conceptTag":"optimistic-ui-updates","explanationAfterAnswer":"Optimistic updates immediately render expected state changes in the UI (e.g. toggling a ''like'' button) without waiting for server round-trip latency, rolling back to the previous state with a notification if the network request errors.","questionNumber":6},{"id":"web-int-7","questionText":"How does code splitting improve the Initial Page Load performance of a large web application?","options":[{"id":"web-int-7-a","label":"A","text":"It minifies HTML whitespace so that CSS files are executed directly by the operating system kernel"},{"id":"web-int-7-b","label":"B","text":"It replaces all external library dependencies with native browser DOM manipulation equivalents"},{"id":"web-int-7-d","label":"C","text":"It splits database queries across multiple relational tables during server-side template compilation"},{"id":"web-int-7-c","label":"D","text":"It breaks the bundle into smaller chunks loaded on demand, reducing the initial JavaScript parsed by the browser"}],"correctOptionId":"web-int-7-c","difficulty":"intermediate","complexity":"application","conceptTag":"code-splitting-bundlers","explanationAfterAnswer":"Rather than shipping a monolithic multi-megabyte bundle, bundlers split code by route or dynamic import (React.lazy), loading only the JavaScript required for the initial route and fetching other chunks lazily.","questionNumber":7},{"id":"web-int-8","questionText":"Why is setting ''HttpOnly'' and ''SameSite=Lax'' flags on session cookies considered standard security practice?","options":[{"id":"web-int-8-d","label":"A","text":"HttpOnly blocks client-side script access mitigating XSS theft, while SameSite restricts cross-site CSRF delivery"},{"id":"web-int-8-a","label":"B","text":"HttpOnly compresses cookie data using gzip, while SameSite encrypts cookies with local public key certificates"},{"id":"web-int-8-b","label":"C","text":"HttpOnly forces the browser to delete session cookies after sixty seconds of inactivity across user tabs"},{"id":"web-int-8-c","label":"D","text":"HttpOnly restricts cookie transmission exclusively to internal private subnets without public internet access"}],"correctOptionId":"web-int-8-d","difficulty":"intermediate","complexity":"challenging","conceptTag":"cookie-security-flags","explanationAfterAnswer":"HttpOnly prevents document.cookie access from JavaScript, thwarting cookie theft via XSS. SameSite=Lax/Strict prevents the browser from sending the cookie in cross-site requests, mitigating CSRF attacks.","questionNumber":8},{"id":"web-int-9","questionText":"What problem occurs when multiple clients update the same database record simultaneously without concurrency controls?","options":[{"id":"web-int-9-b","label":"A","text":"The database server immediately terminates all client TCP sockets and triggers automatic index rebuilds"},{"id":"web-int-9-a","label":"B","text":"The Lost Update anomaly, where the later write unintentionally overwrites changes committed by the earlier write"},{"id":"web-int-9-c","label":"C","text":"The operating system converts the relational database tables into uncompressed plain text CSV archives"},{"id":"web-int-9-d","label":"D","text":"All future client read queries on that table return HTTP 404 Not Found status errors indefinitely"}],"correctOptionId":"web-int-9-a","difficulty":"intermediate","complexity":"challenging","conceptTag":"lost-update-concurrency","explanationAfterAnswer":"In a lost update, Client A and Client B read state X simultaneously. Client A updates X and saves. Client B updates X based on the original read and saves, silently overwriting A''s modifications without knowing. Optimistic concurrency (version checks) resolves this.","questionNumber":9},{"id":"web-int-10","questionText":"How does the browser''s Service Worker API enable Progressive Web App (PWA) offline capability?","options":[{"id":"web-int-10-d","label":"A","text":"By compiling web application TypeScript files into native mobile Android APK files in the background"},{"id":"web-int-10-c","label":"B","text":"By generating synthetic Wi-Fi connections that simulate internet availability using cellular radio hardware"},{"id":"web-int-10-a","label":"C","text":"By embedding a lightweight headless relational database inside the browser''s GPU rendering pipeline"},{"id":"web-int-10-b","label":"D","text":"By acting as a client-side network proxy that intercepts fetch requests and serves cached responses from CacheStorage"}],"correctOptionId":"web-int-10-b","difficulty":"intermediate","complexity":"challenging","conceptTag":"service-worker-cache-storage","explanationAfterAnswer":"Service Workers run in a background thread and intercept network fetch events. When offline, the worker intercepts requests and returns matching cached responses from the CacheStorage API, enabling full offline operation.","questionNumber":10}]'::jsonb, 0, '[]'::jsonb, 0, 'in_progress', '2026-09-07T11:14:07.732Z'::timestamptz, NULL, NULL)
ON CONFLICT (session_id) DO UPDATE SET
  current_question_index = EXCLUDED.current_question_index,
  answers = EXCLUDED.answers,
  time_remaining_seconds = EXCLUDED.time_remaining_seconds,
  status = EXCLUDED.status,
  completed_at = EXCLUDED.completed_at;
INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788782352879_0sw6o', 'fbc5a09c-460f-44d9-afd1-9b409492ea36', 'security', 'Cybersecurity & Defenses', 'intermediate', '[{"id":"sec-int-1","questionText":"How does a Cross-Site Scripting (XSS) attack execute in a target web application?","options":[{"id":"sec-int-1-a","label":"A","text":"By manipulating HTTP caching headers to store sensitive authentication cookies in intermediate proxies"},{"id":"sec-int-1-c","label":"B","text":"By injecting untrusted client script into web application pages that executes in other users'' browsers"},{"id":"sec-int-1-d","label":"C","text":"By corrupting browser DNS cache records to redirect legitimate API requests to adversary endpoints"},{"id":"sec-int-1-b","label":"D","text":"By appending SQL syntax into URL parameters to dump user password hashes from the relational database"}],"correctOptionId":"sec-int-1-c","difficulty":"intermediate","complexity":"fundamental","conceptTag":"xss-vulnerability-mechanism","explanationAfterAnswer":"XSS occurs when an application includes untrusted user input without context-aware encoding, leading the browser to execute injected scripts in the security context of the user.","questionNumber":1},{"id":"sec-int-2","questionText":"Which HTTP header is specifically designed to restrict where scripts, styles, and assets can load from?","options":[{"id":"sec-int-2-d","label":"A","text":"Content-Security-Policy (CSP), declaring authorized sources from which scripts and resources may be loaded"},{"id":"sec-int-2-c","label":"B","text":"Access-Control-Allow-Origin, controlling which external web domains can access cross-origin API responses"},{"id":"sec-int-2-a","label":"C","text":"Strict-Transport-Security (HSTS), enforcing encrypted HTTPS communication for all domain connections"},{"id":"sec-int-2-b","label":"D","text":"X-Frame-Options, preventing malicious sites from rendering the target page inside hidden frame overlays"}],"correctOptionId":"sec-int-2-d","difficulty":"intermediate","complexity":"fundamental","conceptTag":"csp-security-headers","explanationAfterAnswer":"Content-Security-Policy (CSP) allows site operators to restrict the origins of executable scripts, stylesheets, and media, effectively neutralizing unauthorized inline script execution.","questionNumber":2},{"id":"sec-int-3","questionText":"Why are adaptive algorithms like Argon2 and bcrypt preferred over fast hashes like SHA-256 for passwords?","options":[{"id":"sec-int-3-a","label":"A","text":"They incorporate configurable work factors and memory hardness to resist GPU and ASIC brute-force attacks"},{"id":"sec-int-3-b","label":"B","text":"They generate variable-length outputs that eliminate hash collision vulnerabilities across large datasets"},{"id":"sec-int-3-d","label":"C","text":"They eliminate the need for random cryptographic salts by computing deterministic seed values"},{"id":"sec-int-3-c","label":"D","text":"They use asymmetric key pairs requiring separate public and private keys to verify password matches"}],"correctOptionId":"sec-int-3-a","difficulty":"intermediate","complexity":"fundamental","conceptTag":"adaptive-password-hashing","explanationAfterAnswer":"Fast hash functions like SHA-256 are engineered for speed, allowing billions of guesses per second on GPUs. Adaptive functions introduce computational work factors and memory demands to thwart hardware cracking.","questionNumber":3},{"id":"sec-int-4","questionText":"A security analyst observes high volumes of outbound DNS queries for random hex subdomains. What is the threat?","options":[{"id":"sec-int-4-b","label":"A","text":"DNS tunneling and data exfiltration encoding unauthorized data within sequential lookup query labels"},{"id":"sec-int-4-d","label":"B","text":"Dynamic DNS client registration updating external public IP address bindings following lease renewal"},{"id":"sec-int-4-c","label":"C","text":"Authoritative name server zone synchronization transferring DNS resource records to secondary servers"},{"id":"sec-int-4-a","label":"D","text":"Standard browser cache prefetching optimizing domain name resolution latency for anticipated user clicks"}],"correctOptionId":"sec-int-4-b","difficulty":"intermediate","complexity":"application","conceptTag":"dns-tunneling-exfiltration","explanationAfterAnswer":"DNS tunneling encapsulates non-DNS traffic or stolen data inside DNS queries (e.g. data.attacker.com), bypassing standard egress firewall rules that leave port 53 open.","questionNumber":4},{"id":"sec-int-5","questionText":"What is the most robust defense against SQL Injection vulnerabilities in modern web applications?","options":[{"id":"sec-int-5-d","label":"A","text":"Restricting database connections to communicate exclusively over mutually authenticated TLS sockets"},{"id":"sec-int-5-b","label":"B","text":"Storing database credentials in encrypted configuration files rather than hardcoding them in source"},{"id":"sec-int-5-a","label":"C","text":"Filtering incoming request parameters with regular expressions to remove single quotes and semicolons"},{"id":"sec-int-5-c","label":"D","text":"Using parameterized queries (prepared statements) that separate user input from SQL command structure"}],"correctOptionId":"sec-int-5-c","difficulty":"intermediate","complexity":"application","conceptTag":"parameterized-queries-sqli","explanationAfterAnswer":"Parameterized queries ensure the database driver treats user input strictly as data values, preventing user input from altering the compiled SQL query syntax.","questionNumber":5},{"id":"sec-int-6","questionText":"What security advantage does network micro-segmentation provide inside a corporate infrastructure?","options":[{"id":"sec-int-6-b","label":"A","text":"It removes the operational requirement to apply operating system security updates on internal servers"},{"id":"sec-int-6-d","label":"B","text":"It isolates workloads into discrete zones, preventing adversaries from moving laterally if a host is breached"},{"id":"sec-int-6-c","label":"C","text":"It automates edge router failover by dynamically re-routing external traffic across redundant gateways"},{"id":"sec-int-6-a","label":"D","text":"It increases raw packet throughput by bypassing perimeter firewall inspection for internal subnet traffic"}],"correctOptionId":"sec-int-6-d","difficulty":"intermediate","complexity":"application","conceptTag":"network-microsegmentation","explanationAfterAnswer":"Micro-segmentation restricts communication between workloads according to granular policies, limiting an attacker''s ability to move laterally across an internal network.","questionNumber":6},{"id":"sec-int-7","questionText":"If an API verifies JWTs without enforcing the signature algorithm (accepting ''alg: none''), what attack occurs?","options":[{"id":"sec-int-7-c","label":"A","text":"Attackers can bypass Cross-Origin Resource Sharing (CORS) preflight validation on protected endpoints"},{"id":"sec-int-7-a","label":"B","text":"Attackers can forge arbitrary claims and tamper with tokens without needing a valid cryptographic signature"},{"id":"sec-int-7-b","label":"C","text":"Attackers can cause server denial of service by triggering recursive cryptographic verification routines"},{"id":"sec-int-7-d","label":"D","text":"Attackers can force identity servers to issue refresh tokens with permanent operational validity periods"}],"correctOptionId":"sec-int-7-a","difficulty":"intermediate","complexity":"application","conceptTag":"jwt-none-algorithm-flaw","explanationAfterAnswer":"If a server blindly honors ''alg: none'', an attacker can modify the token payload (e.g. elevating role to admin) and strip the signature, gaining unauthorized privileges.","questionNumber":7},{"id":"sec-int-8","questionText":"What is the primary security goal of implementing the Principle of Least Privilege (PoLP)?","options":[{"id":"sec-int-8-b","label":"A","text":"To restrict user and process permissions strictly to what is necessary, minimizing potential blast radius"},{"id":"sec-int-8-c","label":"B","text":"To eliminate the need for administrative accounts by delegating all operational tasks to background services"},{"id":"sec-int-8-d","label":"C","text":"To enforce automatic session logout whenever an authenticated user remains inactive for fifteen minutes"},{"id":"sec-int-8-a","label":"D","text":"To reduce cloud infrastructure billing costs by removing unused role-based access control assignments"}],"correctOptionId":"sec-int-8-b","difficulty":"intermediate","complexity":"challenging","conceptTag":"least-privilege-principle","explanationAfterAnswer":"Least Privilege dictates that users, processes, and systems should hold only the bare minimum permissions required to perform their functions, containing damage from compromise.","questionNumber":8},{"id":"sec-int-9","questionText":"How does Online Certificate Status Protocol (OCSP) Stapling improve upon traditional revocation checking?","options":[{"id":"sec-int-9-d","label":"A","text":"It replaces asymmetric public key infrastructure with symmetric shared secret keys across web browsers"},{"id":"sec-int-9-b","label":"B","text":"It embeds the revocation status of all public certificates directly into local operating system trust stores"},{"id":"sec-int-9-a","label":"C","text":"It allows web clients to query multiple Certificate Authorities concurrently to verify root trust chains"},{"id":"sec-int-9-c","label":"D","text":"It allows web servers to deliver timestamped, CA-signed revocation proof during the TLS handshake"}],"correctOptionId":"sec-int-9-c","difficulty":"intermediate","complexity":"challenging","conceptTag":"ocsp-stapling-pki","explanationAfterAnswer":"OCSP Stapling delegates status retrieval to the web server, which caches a signed OCSP response and presents it to connecting clients during TLS negotiation, enhancing speed and privacy.","questionNumber":9},{"id":"sec-int-10","questionText":"Which defense effectively prevents Cross-Site Request Forgery (CSRF) on state-changing web endpoints?","options":[{"id":"sec-int-10-b","label":"A","text":"Encoding all incoming form parameters into base64 strings before processing them in application controllers"},{"id":"sec-int-10-c","label":"B","text":"Mandating password complexity rules that enforce credential changes every thirty days for active users"},{"id":"sec-int-10-d","label":"C","text":"Validating unpredictable anti-CSRF tokens and using SameSite cookie flags on state-changing requests"},{"id":"sec-int-10-a","label":"D","text":"Restricting all backend database transactions to execute in read-only mode for unauthenticated client sessions"}],"correctOptionId":"sec-int-10-d","difficulty":"intermediate","complexity":"challenging","conceptTag":"csrf-mitigation-tokens","explanationAfterAnswer":"CSRF protection requires unpredictable anti-CSRF tokens tied to the user''s session that third-party sites cannot read or guess, alongside SameSite cookie attributes.","questionNumber":10}]'::jsonb, 0, '[]'::jsonb, 0, 'completed', '2026-09-07T11:59:12.879Z'::timestamptz, NULL, NULL)
ON CONFLICT (session_id) DO UPDATE SET
  current_question_index = EXCLUDED.current_question_index,
  answers = EXCLUDED.answers,
  time_remaining_seconds = EXCLUDED.time_remaining_seconds,
  status = EXCLUDED.status,
  completed_at = EXCLUDED.completed_at;
INSERT INTO public.knowledge_test_sessions (session_id, student_id, domain_id, domain_name, difficulty, questions, current_question_index, answers, time_remaining_seconds, status, started_at, completed_at, expires_at)
VALUES ('ktest_1788782359935_tto6l', 'fbc5a09c-460f-44d9-afd1-9b409492ea36', 'security', 'Cybersecurity & Defenses', 'advanced', '[{"id":"sec-adv-1","questionText":"What underlying microarchitectural processor mechanism enables Spectre speculative execution side-channel attacks?","options":[{"id":"sec-adv-1-a","label":"A","text":"Branch predictors executing instructions speculatively past bounds checks and leaving cache timing traces"},{"id":"sec-adv-1-c","label":"B","text":"Hardware thermal throttling desynchronizing clock cycles between physical processor execution cores"},{"id":"sec-adv-1-b","label":"C","text":"Memory management unit page table fragmentation allowing unprivileged user space to read kernel frames"},{"id":"sec-adv-1-d","label":"D","text":"Improper cyclic redundancy checks on L1 data cache lines during asynchronous direct memory access"}],"correctOptionId":"sec-adv-1-a","difficulty":"advanced","complexity":"fundamental","conceptTag":"spectre-microarchitectural-flaw","explanationAfterAnswer":"Spectre exploits speculative execution where CPUs predict branch targets and execute code before bounds checks complete. When squashed, cache state changes persist and leak data via timing attacks.","questionNumber":1},{"id":"sec-adv-2","questionText":"In modern binary exploitation, what is the primary purpose of Return-Oriented Programming (ROP)?","options":[{"id":"sec-adv-2-a","label":"A","text":"To defeat Address Space Layout Randomization by brute-forcing fixed virtual memory offsets in running processes"},{"id":"sec-adv-2-c","label":"B","text":"To accelerate reverse engineering by translating raw assembly opcodes into structured control flow graphs"},{"id":"sec-adv-2-b","label":"C","text":"To defeat Data Execution Prevention (W^X / DEP) by chaining existing executable instruction sequences ending in ret"},{"id":"sec-adv-2-d","label":"D","text":"To execute kernel shellcode by directly corrupting the hardware interrupt descriptor table from user space"}],"correctOptionId":"sec-adv-2-b","difficulty":"advanced","complexity":"application","conceptTag":"rop-dep-bypass","explanationAfterAnswer":"When memory regions are marked non-executable (DEP/NX), ROP circumvents this by reusing existing snippets of executable binary code (''gadgets'') ending in return instructions to build arbitrary logic.","questionNumber":2},{"id":"sec-adv-3","questionText":"How is Kernel Address Space Layout Randomization (KASLR) typically defeated during exploit development?","options":[{"id":"sec-adv-3-c","label":"A","text":"By using an information leak vulnerability that reveals a kernel pointer to calculate the randomized base offset"},{"id":"sec-adv-3-a","label":"B","text":"By transmitting high-volume ICMP echo requests to exhaust kernel socket buffer memory allocations"},{"id":"sec-adv-3-b","label":"C","text":"By corrupting the system real-time clock to desynchronize kernel random number generator initialization"},{"id":"sec-adv-3-d","label":"D","text":"By modifying system security limits in user space configuration files to exceed kernel allocation limits"}],"correctOptionId":"sec-adv-3-c","difficulty":"advanced","complexity":"application","conceptTag":"kaslr-bypass-infoleak","explanationAfterAnswer":"KASLR randomizes the base memory location of kernel code. Attackers leverage an information disclosure bug that leaks a known kernel function pointer to calculate the base slide offset.","questionNumber":3},{"id":"sec-adv-4","questionText":"In Kubernetes, which container configuration enables an attacker to perform a host node breakout?","options":[{"id":"sec-adv-4-d","label":"A","text":"Running in privileged mode with hostPID and hostNetwork enabled or the host filesystem mounted read-write"},{"id":"sec-adv-4-b","label":"B","text":"Attaching a Horizontal Pod Autoscaler that adjusts pod replica counts based on CPU utilization metrics"},{"id":"sec-adv-4-c","label":"C","text":"Deploying a container image built on minimal Alpine Linux rather than an enterprise Linux distribution"},{"id":"sec-adv-4-a","label":"D","text":"Configuring the pod to resolve DNS through cluster CoreDNS services rather than node-local caching daemons"}],"correctOptionId":"sec-adv-4-d","difficulty":"advanced","complexity":"application","conceptTag":"container-escape-privilege","explanationAfterAnswer":"Privileged containers disable Linux cgroup and namespace isolation. Access to host devices or the root filesystem allows escape via chroot, device access, or cgroup release agent manipulation.","questionNumber":4},{"id":"sec-adv-5","questionText":"What condition permits an attacker to perform a Blind Time-Based SQL Injection attack against an API?","options":[{"id":"sec-adv-5-a","label":"A","text":"The endpoint returns identical responses regardless of query results, but evaluates injected delay functions"},{"id":"sec-adv-5-d","label":"B","text":"The application communicates with the database over an unencrypted network connection without TLS verification"},{"id":"sec-adv-5-c","label":"C","text":"The database connection pool suffers from connection starvation due to unindexed queries on large tables"},{"id":"sec-adv-5-b","label":"D","text":"The database server exposes detailed error stack traces and internal schema definitions in HTTP 500 responses"}],"correctOptionId":"sec-adv-5-a","difficulty":"advanced","complexity":"challenging","conceptTag":"blind-time-based-sqli","explanationAfterAnswer":"When an application leaks no data or differential error messages, an attacker injects conditional time-delay commands (like pg_sleep or WAITFOR DELAY) to infer data bit-by-bit from response times.","questionNumber":5},{"id":"sec-adv-6","questionText":"In SAML 2.0 implementations, what design flaw enables XML Signature Wrapping (XSW) attacks?","options":[{"id":"sec-adv-6-c","label":"A","text":"A mismatch between namespace resolution during signature verification and resolution during assertion processing"},{"id":"sec-adv-6-d","label":"B","text":"A mismatch between schema validation of the assertion and resolution of referenced signed element identifiers"},{"id":"sec-adv-6-a","label":"C","text":"A mismatch between the XML structure used during signature canonicalization and that interpreted by the app"},{"id":"sec-adv-6-b","label":"D","text":"A mismatch between the XML node validated by the signature verifier and the node consumed by business logic"}],"correctOptionId":"sec-adv-6-b","difficulty":"advanced","complexity":"challenging","conceptTag":"saml-xml-signature-wrapping","explanationAfterAnswer":"XSW exploits architectural discrepancies where signature verification validates an intact assertion, while business logic retrieves user claims from an unsigned, wrapped element elsewhere in the DOM.","questionNumber":6},{"id":"sec-adv-7","questionText":"What cryptographic flaw made WPA2''s 4-way handshake vulnerable to Key Reinstallation Attacks (KRACK)?","options":[{"id":"sec-adv-7-a","label":"A","text":"The access point using weak Diffie-Hellman primes that allow pre-computation attacks against session keys"},{"id":"sec-adv-7-b","label":"B","text":"The authentication server transmitting the master pre-shared key in plaintext beacon frames during discovery"},{"id":"sec-adv-7-d","label":"C","text":"The wireless controller generating predictable initialization vectors during RC4 stream cipher encapsulation"},{"id":"sec-adv-7-c","label":"D","text":"The client reinstalling an in-use pairwise key upon receiving retransmitted Message 3, resetting the packet counter"}],"correctOptionId":"sec-adv-7-c","difficulty":"advanced","complexity":"challenging","conceptTag":"krack-wpa2-handshake","explanationAfterAnswer":"KRACK exploits Message 3 retransmission. When re-received, vulnerable clients reinstall the already active PTK and reset its transmit replay counter (nonce), enabling keystream reuse attacks.","questionNumber":7},{"id":"sec-adv-8","questionText":"Why is ML-KEM (Kyber) categorized as lattice-based post-quantum cryptography?","options":[{"id":"sec-adv-8-d","label":"A","text":"Its security relies on high-dimensional lattice vector problems that cannot be solved efficiently by Shor''s algorithm"},{"id":"sec-adv-8-c","label":"B","text":"It generates symmetric one-time pads derived from cosmic background radiation sensors embedded in security modules"},{"id":"sec-adv-8-a","label":"C","text":"It employs quantum key distribution channels that leverage photon entanglement to detect eavesdropping on optical lines"},{"id":"sec-adv-8-b","label":"D","text":"It utilizes super-singular elliptic curve isogenies requiring exponential classical resources to compute path morphisms"}],"correctOptionId":"sec-adv-8-d","difficulty":"advanced","complexity":"challenging","conceptTag":"post-quantum-lattice-crypto","explanationAfterAnswer":"ML-KEM security reduces to the Module Learning with Errors (M-LWE) problem over high-dimensional lattices, which resists both classical algorithms and quantum attacks based on Shor''s algorithm.","questionNumber":8},{"id":"sec-adv-9","questionText":"In eBPF security observability tooling, how can a root-privileged adversary attempt to blind kernel telemetry?","options":[{"id":"sec-adv-9-b","label":"A","text":"By modifying userspace /etc/resolv.conf configuration files to redirect internal DNS queries to external resolvers"},{"id":"sec-adv-9-c","label":"B","text":"By installing unapproved compilers on the host worker node to trigger local static binary analysis warnings"},{"id":"sec-adv-9-a","label":"C","text":"By detaching kernel tracepoints via bpf syscalls or flooding the ring buffer to induce massive unlogged event drops"},{"id":"sec-adv-9-d","label":"D","text":"By adjusting system timezone configurations to create clock drift between worker nodes and the control plane"}],"correctOptionId":"sec-adv-9-a","difficulty":"advanced","complexity":"challenging","conceptTag":"ebpf-telemetry-evasion","explanationAfterAnswer":"An adversary with root or CAP_BPF can interact directly with the bpf() syscall to detach attached probes, corrupt BPF maps, or generate high-volume synthetic events to overflow ring buffers.","questionNumber":9},{"id":"sec-adv-10","questionText":"Which defense mechanism specifically protects cloud instance metadata endpoints (169.254.169.254) against SSRF?","options":[{"id":"sec-adv-10-c","label":"A","text":"Encoding all outbound HTTP request bodies into base64 strings before transmitting them over network gateways"},{"id":"sec-adv-10-a","label":"B","text":"Configuring public DNS records to map internal private IP subnets to corporate reverse proxy load balancers"},{"id":"sec-adv-10-d","label":"C","text":"Enforcing multi-factor authentication on all administrative SSH connections established to worker compute nodes"},{"id":"sec-adv-10-b","label":"D","text":"Enforcing IMDSv2 requiring session-oriented PUT requests with signed token headers alongside strict egress filtering"}],"correctOptionId":"sec-adv-10-b","difficulty":"advanced","complexity":"challenging","conceptTag":"imdsv2-ssrf-mitigation","explanationAfterAnswer":"IMDSv2 requires clients to first execute a PUT request to generate a session token (which standard SSRF vectors cannot easily forge) before querying metadata, and sets token hop limits to block proxies.","questionNumber":10}]'::jsonb, 0, '[]'::jsonb, 0, 'completed', '2026-09-07T11:59:19.935Z'::timestamptz, NULL, NULL)
