VALUES ('ktest_1788868286638_bultf', '1ff7662b-94c3-4c76-ac2d-039c6116499b', 'security', 'Cybersecurity & Defense', 'advanced', '[{"id":"sec-adv-1","questionText":"What underlying microarchitectural processor mechanism enables Spectre speculative execution side-channel attacks?","options":[{"id":"sec-adv-1-b","label":"A","text":"Memory management unit page table fragmentation allowing unprivileged user space to read kernel frames"},{"id":"sec-adv-1-d","label":"B","text":"Improper cyclic redundancy checks on L1 data cache lines during asynchronous direct memory access"},{"id":"sec-adv-1-a","label":"C","text":"Branch predictors executing instructions speculatively past bounds checks and leaving cache timing traces"},{"id":"sec-adv-1-c","label":"D","text":"Hardware thermal throttling desynchronizing clock cycles between physical processor execution cores"}],"correctOptionId":"sec-adv-1-a","difficulty":"advanced","complexity":"fundamental","conceptTag":"spectre-microarchitectural-flaw","explanationAfterAnswer":"Spectre exploits speculative execution where CPUs predict branch targets and execute code before bounds checks complete. When squashed, cache state changes persist and leak data via timing attacks.","questionNumber":1},{"id":"sec-adv-2","questionText":"In modern binary exploitation, what is the primary purpose of Return-Oriented Programming (ROP)?","options":[{"id":"sec-adv-2-b","label":"A","text":"To defeat Data Execution Prevention (W^X / DEP) by chaining existing executable instruction sequences ending in ret"},{"id":"sec-adv-2-d","label":"B","text":"To execute kernel shellcode by directly corrupting the hardware interrupt descriptor table from user space"},{"id":"sec-adv-2-c","label":"C","text":"To accelerate reverse engineering by translating raw assembly opcodes into structured control flow graphs"},{"id":"sec-adv-2-a","label":"D","text":"To defeat Address Space Layout Randomization by brute-forcing fixed virtual memory offsets in running processes"}],"correctOptionId":"sec-adv-2-b","difficulty":"advanced","complexity":"application","conceptTag":"rop-dep-bypass","explanationAfterAnswer":"When memory regions are marked non-executable (DEP/NX), ROP circumvents this by reusing existing snippets of executable binary code (''gadgets'') ending in return instructions to build arbitrary logic.","questionNumber":2},{"id":"sec-adv-3","questionText":"How is Kernel Address Space Layout Randomization (KASLR) typically defeated during exploit development?","options":[{"id":"sec-adv-3-a","label":"A","text":"By transmitting high-volume ICMP echo requests to exhaust kernel socket buffer memory allocations"},{"id":"sec-adv-3-c","label":"B","text":"By using an information leak vulnerability that reveals a kernel pointer to calculate the randomized base offset"},{"id":"sec-adv-3-b","label":"C","text":"By corrupting the system real-time clock to desynchronize kernel random number generator initialization"},{"id":"sec-adv-3-d","label":"D","text":"By modifying system security limits in user space configuration files to exceed kernel allocation limits"}],"correctOptionId":"sec-adv-3-c","difficulty":"advanced","complexity":"application","conceptTag":"kaslr-bypass-infoleak","explanationAfterAnswer":"KASLR randomizes the base memory location of kernel code. Attackers leverage an information disclosure bug that leaks a known kernel function pointer to calculate the base slide offset.","questionNumber":3},{"id":"sec-adv-4","questionText":"In Kubernetes, which container configuration enables an attacker to perform a host node breakout?","options":[{"id":"sec-adv-4-d","label":"A","text":"Running in privileged mode with hostPID and hostNetwork enabled or the host filesystem mounted read-write"},{"id":"sec-adv-4-a","label":"B","text":"Configuring the pod to resolve DNS through cluster CoreDNS services rather than node-local caching daemons"},{"id":"sec-adv-4-b","label":"C","text":"Attaching a Horizontal Pod Autoscaler that adjusts pod replica counts 